import Foundation

/// North Carolina criminal law, as used in the simulator.
///
/// Offense classes and sentencing ranges follow the North Carolina General Statutes
/// and the Structured Sentencing punishment charts for offenses committed on or after
/// October 1, 2013. Statutes are summarized and simplified for the game.
enum LawLibrary {
    static let jurisdiction = "North Carolina"
    static let disclaimer = "Based on the North Carolina General Statutes and Structured Sentencing charts, summarized and simplified for a simulator. Laws change; this is not legal advice. Hollis County and everyone in it are fictional."

    static let all: [Law] = offenses + doctrines

    private static let byID: [String: Law] = Dictionary(uniqueKeysWithValues: all.map { ($0.id, $0) })

    static func law(_ id: String) -> Law {
        if let law = byID[id] { return law }
        assertionFailure("Unknown law id: \(id)")
        return Law(id: id, statute: "—", title: id, category: .procedure, summary: "Missing entry.", elements: [])
    }

    static func lawIfPresent(_ id: String) -> Law? { byID[id] }

    // MARK: - Offenses

    static let offenses: [Law] = violent + robbery + property + drugs + whiteCollar + publicOrder + traffic + cyber + family

    static let violent: [Law] = [
        Law(id: "attemptedMurder1", statute: "G.S. 14-17; 14-2.5", title: "Attempted First-Degree Murder", category: .violent, ncClass: .B2,
            summary: "An overt act, done with premeditation, deliberation, and the specific intent to kill, that goes beyond preparation but falls short of killing.",
            elements: ["The defendant intended to kill the victim.", "With premeditation and deliberation.", "The defendant committed an overt act calculated to bring about the killing.", "The act went beyond mere preparation.", "The killing did not occur."],
            defenses: ["Lack of specific intent", "Self-defense", "Abandonment is not a defense once the attempt is complete"],
            related: ["murder1"],
            notes: "Punished as a Class B2 felony."),
        Law(id: "assaultPointingGun", statute: "G.S. 14-34", title: "Assault by Pointing a Gun", category: .violent, ncClass: .misdA1,
            summary: "Intentionally pointing a gun at another person without legal justification, whether or not it is loaded.",
            elements: ["The defendant pointed a gun at the victim.", "Intentionally.", "Without legal justification."],
            defenses: ["Self-defense", "Defense of others", "Accident"],
            related: ["awdw"]),
        Law(id: "interferingEmergency", statute: "G.S. 14-286.2", title: "Interfering with an Emergency Communication", category: .violent, ncClass: .misdA1,
            summary: "Intentionally interfering with another person's attempt to call 911 or otherwise seek emergency help while that person reasonably believes they need it.",
            elements: ["The victim was attempting to make an emergency communication.", "The victim reasonably believed they needed help.", "The defendant intentionally interfered."],
            defenses: ["No interference", "No emergency reasonably believed"],
            related: ["dvpoViolation"]),
        Law(id: "dischargingOccupied", statute: "G.S. 14-34.1(b)", title: "Discharging a Weapon into Occupied Property", category: .violent, ncClass: .D,
            summary: "Willfully discharging a firearm into an occupied dwelling or occupied vehicle in operation.",
            elements: ["The defendant willfully discharged a firearm.", "Into a dwelling, or a vehicle in operation.", "The property was occupied at the time.", "The defendant knew or had reasonable grounds to believe it was occupied."],
            defenses: ["Misidentification", "Lack of knowledge that the property was occupied"],
            related: ["awdwikisi", "felonFirearm"],
            notes: "Discharging into other occupied property is Class E; if serious bodily injury results, Class C."),
        Law(id: "assaultLEO", statute: "G.S. 14-34.7(c)", title: "Assault on a Law Enforcement Officer Inflicting Physical Injury", category: .violent, ncClass: .I,
            summary: "Assaulting a law enforcement officer, probation officer, or detention officer in the performance of duties, inflicting physical injury.",
            elements: ["The victim was a law enforcement, probation, or detention officer.", "Performing official duties.", "The defendant assaulted the officer.", "Inflicting physical injury."],
            defenses: ["Self-defense against excessive force", "No physical injury (reduces to a misdemeanor)"],
            related: ["assaultGovOfficial", "resisting"]),
        Law(id: "assaultGovOfficial", statute: "G.S. 14-33(c)(4)", title: "Assault on a Government Officer or Employee", category: .violent, ncClass: .misdA1,
            summary: "Assaulting an officer or employee of the State or a local government while they are discharging, or attempting to discharge, official duties.",
            elements: ["The victim was a government officer or employee.", "Discharging official duties.", "The defendant assaulted the victim."],
            related: ["assaultLEO", "simpleAssault"]),
        Law(id: "murder1", statute: "G.S. 14-17(a)", title: "First-Degree Murder", category: .violent, ncClass: .A,
            summary: "A willful, deliberate, and premeditated killing; a killing by poison, lying in wait, imprisonment, starving, or torture; or a killing during certain felonies (felony murder).",
            elements: ["The defendant unlawfully killed the victim.",
                       "The defendant acted with malice.",
                       "The defendant acted with premeditation (thought about it beforehand, for any length of time) and deliberation (in a cool state of blood), OR the killing was by poison, lying in wait, torture, or during a qualifying felony."],
            specialPunishment: "Life imprisonment without parole, or death if the State proceeds capitally. A defendant 18 or older convicted in a non-capital case receives life without parole; there is no judicial discretion.",
            defenses: ["Self-defense", "Insanity", "Voluntary intoxication negating premeditation", "Diminished capacity"],
            related: ["murder2", "volManslaughter", "juryWaiver"],
            notes: "A jury cannot be waived when the State seeks the death penalty. Every bench trial for murder is non-capital."),
        Law(id: "murder2", statute: "G.S. 14-17(b)", title: "Second-Degree Murder", category: .violent, ncClass: .B1,
            summary: "An unlawful killing with malice but without premeditation and deliberation.",
            elements: ["The defendant unlawfully killed the victim.",
                       "The defendant acted with malice: express hatred or ill will, an intentional act that is inherently dangerous to life, or a mind utterly without regard for human life.",
                       "The defendant's act was a proximate cause of death."],
            defenses: ["Self-defense", "Heat of passion (reduces to voluntary manslaughter)", "Accident"],
            related: ["murder1", "volManslaughter", "selfDefense"],
            notes: "Class B2 when malice is based only on recklessness so extreme it shows disregard for life, or when the death resulted from unlawful drug distribution. Otherwise Class B1."),
        Law(id: "volManslaughter", statute: "G.S. 14-18", title: "Voluntary Manslaughter", category: .violent, ncClass: .D,
            summary: "An intentional killing without malice, done in the heat of passion on sudden and adequate provocation, or in imperfect self-defense.",
            elements: ["The defendant intentionally killed the victim.",
                       "The killing was in the heat of passion caused by adequate provocation, with no time for passion to cool, OR",
                       "The defendant believed deadly force was necessary but that belief was unreasonable, or the defendant used excessive force or was the initial aggressor (imperfect self-defense)."],
            defenses: ["Perfect self-defense (complete acquittal)"],
            related: ["murder2", "invManslaughter", "imperfectSelfDefense"]),
        Law(id: "invManslaughter", statute: "G.S. 14-18", title: "Involuntary Manslaughter", category: .violent, ncClass: .F,
            summary: "An unintentional killing caused by an unlawful act not amounting to a felony, or by culpable negligence.",
            elements: ["The defendant acted unlawfully or with culpable negligence (reckless disregard for the safety of others).",
                       "That conduct proximately caused the victim's death."],
            defenses: ["Accident without culpable negligence", "Intervening cause"],
            related: ["murder2", "felonyDBV"]),
        Law(id: "awdwikisi", statute: "G.S. 14-32(a)", title: "Assault with a Deadly Weapon with Intent to Kill Inflicting Serious Injury", category: .violent, ncClass: .C,
            summary: "Assaulting someone with a deadly weapon, intending to kill, and inflicting serious injury.",
            elements: ["The defendant assaulted the victim.", "With a deadly weapon.", "With intent to kill.", "Inflicting serious injury."],
            defenses: ["Self-defense", "Defense of others", "Lack of intent to kill (reduces the charge)"],
            related: ["awdwisi", "awdwik"]),
        Law(id: "awdwik", statute: "G.S. 14-32(c)", title: "Assault with a Deadly Weapon with Intent to Kill", category: .violent, ncClass: .E,
            summary: "Assaulting someone with a deadly weapon with intent to kill, whether or not injury results.",
            elements: ["The defendant assaulted the victim.", "With a deadly weapon.", "With intent to kill."],
            defenses: ["Self-defense", "Defense of others"],
            related: ["awdwikisi", "awdw"]),
        Law(id: "awdwisi", statute: "G.S. 14-32(b)", title: "Assault with a Deadly Weapon Inflicting Serious Injury", category: .violent, ncClass: .E,
