                       "Inflicting serious injury, such as broken bones, hospitalization, or lasting pain or impairment."],
            defenses: ["Self-defense", "Defense of others", "Accident"],
            related: ["aisi", "awdw", "selfDefense"]),
        Law(id: "aisi", statute: "G.S. 14-33(c)(1)", title: "Assault Inflicting Serious Injury", category: .violent, ncClass: .misdA1,
