            elements: ["The defendant assaulted the victim.", "With a deadly weapon."],
            defenses: ["Self-defense", "Defense of others"],
            related: ["awdwisi", "simpleAssault"]),
        Law(id: "assaultFemale", statute: "G.S. 14-33(c)(2)", title: "Assault on a Female", category: .violent, ncClass: .misdA1,
