            related: ["simpleAssault", "strangulation", "habitualMisdAssault"]),
        Law(id: "strangulation", statute: "G.S. 14-32.4(b)", title: "Assault Inflicting Physical Injury by Strangulation", category: .violent, ncClass: .H,
            summary: "An assault that inflicts physical injury by strangulation.",
            elements: ["The defendant assaulted the victim.", "By strangulation.", "Inflicting physical injury."],
