            summary: "Vaginal intercourse with another person by force and against that person's will, or with a person the defendant knows or should reasonably know is physically helpless or mentally incapacitated.",
            elements: ["The defendant engaged in vaginal intercourse with the victim.", "By force and against the victim's will, or with a victim the defendant knew or should reasonably have known was physically helpless or mentally incapacitated."],
            related: ["sexualBattery"]),
        Law(id: "sexualBattery", statute: "G.S. 14-27.33", title: "Sexual Battery", category: .violent, ncClass: .misdA1,
