    static let robbery: [Law] = [
        Law(id: "conspiracyRobbery", statute: "G.S. 14-2.4; 14-87", title: "Conspiracy to Commit Robbery with a Dangerous Weapon", category: .robbery, ncClass: .E,
            summary: "An agreement between two or more people to commit armed robbery. The crime is complete when the agreement is made.",
            elements: ["The defendant agreed with at least one other person.", "To commit robbery with a dangerous weapon.", "Intending that the agreement be carried out."],
            defenses: ["No agreement", "Mere presence or association"],
            related: ["dangerousRobbery"],
            notes: "Punished one class lower than the robbery itself."),
        Law(id: "witnessIntimidation", statute: "G.S. 14-226", title: "Intimidating a Witness", category: .robbery, ncClass: .G,
            summary: "Attempting by threats, menaces, or force to intimidate or deter a person summoned or acting as a witness in a court proceeding.",
            elements: ["The victim was a witness or prospective witness in a court proceeding.", "The defendant, by threats, menaces, or force, attempted to intimidate or deter the witness from testifying or to influence the testimony."],
            related: ["obstruction", "communicatingThreats"]),
        Law(id: "communicatingThreats", statute: "G.S. 14-277.1", title: "Communicating Threats", category: .robbery, ncClass: .misd1,
            summary: "Willfully threatening to physically injure a person or damage property, communicated in a way that a reasonable person would believe it is likely to be carried out.",
            elements: ["The defendant willfully threatened to injure a person or damage their property.", "The threat was communicated orally, in writing, or by other means.", "Under the circumstances, a reasonable person would believe the threat was likely to be carried out.", "The person threatened believed it would be carried out."],
            defenses: ["Hyperbole or jest", "First Amendment: not a true threat (Counterman v. Colorado requires at least recklessness)"],
            related: ["massViolenceThreat", "stalking"]),
        Law(id: "dangerousRobbery", statute: "G.S. 14-87", title: "Robbery with a Firearm or Other Dangerous Weapon", category: .robbery, ncClass: .D,
            summary: "Taking personal property from another's person or presence, by use or threatened use of a firearm or dangerous weapon, endangering or threatening the person's life. Often called \"armed robbery.\"",
            elements: ["The defendant took personal property from the person or presence of another.",
                       "Without consent, and with intent to permanently deprive.",
                       "By possessing, using, or threatening to use a firearm or other dangerous weapon.",
                       "Whereby the life of a person was endangered or threatened."],
            defenses: ["Misidentification", "The object was not a dangerous weapon (reduces to common law robbery)"],
            related: ["commonLawRobbery", "felonFirearm"],
            notes: "If the victim reasonably believed the object was a firearm, the State need not prove it was real. Evidence that it was fake can rebut that inference."),
        Law(id: "commonLawRobbery", statute: "G.S. 14-87.1", title: "Common Law Robbery", category: .robbery, ncClass: .G,
            summary: "Taking property from another's person or presence by violence or by putting the person in fear.",
            elements: ["The defendant took property from the person or presence of another.",
                       "Without consent, intending to permanently deprive.",
                       "By violence or by putting the person in fear."],
            defenses: ["Misidentification", "Claim of right"],
            related: ["dangerousRobbery", "felonyLarceny"]),
        Law(id: "kidnapping1", statute: "G.S. 14-39", title: "First-Degree Kidnapping", category: .robbery, ncClass: .C,
            summary: "Kidnapping where the victim was not released in a safe place, or was seriously injured or sexually assaulted.",
            elements: ["The defendant unlawfully confined, restrained, or removed a person 16 or older without consent.",
                       "For a purpose listed in the statute, e.g. ransom, facilitating a felony, terrorizing, or doing serious bodily harm.",
                       "The victim was not released in a safe place, or was seriously injured or sexually assaulted."],
            related: ["kidnapping2"]),
        Law(id: "kidnapping2", statute: "G.S. 14-39", title: "Second-Degree Kidnapping", category: .robbery, ncClass: .E,
            summary: "Kidnapping where the victim was released in a safe place and not seriously injured or sexually assaulted.",
            elements: ["The defendant unlawfully confined, restrained, or removed a person.",
                       "For a statutory purpose.",
                       "The restraint was separate from that inherent in another felony."],
            related: ["kidnapping1", "transportChild"]),
        Law(id: "stalking", statute: "G.S. 14-277.3A", title: "Stalking", category: .robbery, ncClass: .misdA1,
            summary: "Willfully engaging in a course of conduct directed at a specific person, knowing it would cause a reasonable person to fear for their safety or suffer substantial emotional distress.",
            elements: ["The defendant willfully harassed or engaged in a course of conduct (two or more acts) directed at the victim.",
                       "This includes following, monitoring, surveilling, threatening, or communicating, including by electronic devices.",
                       "The defendant knew or should have known it would cause a reasonable person to fear for their safety or the safety of family, or to suffer substantial emotional distress."],
            defenses: ["Legitimate purpose", "No course of conduct"],
            related: ["cyberstalking", "privateImages"],
            notes: "First offense is a Class A1 misdemeanor. Committing it while a court order prohibits similar conduct raises it to a Class H felony; a second stalking conviction is a Class F felony.")
    ]

