            defenses: ["Necessity / justification (rarely succeeds)", "No intent to violate the order"],
            related: ["kidnapping2", "necessity"],
            notes: "Keeping the child outside the state for more than 72 hours is presumed to be intent to violate the order."),
        Law(id: "childAbuseMisd", statute: "G.S. 14-318.2", title: "Misdemeanor Child Abuse", category: .family, ncClass: .misdA1,
            summary: "A parent or caretaker of a child under 16 who inflicts, allows, or creates a substantial risk of physical injury to the child by other than accidental means.",
            elements: ["The defendant was a parent or caretaker of a child under 16.", "The defendant inflicted, allowed, or created a substantial risk of physical injury.", "By other than accidental means."],
            related: [])
    ]

    // MARK: - Doctrines

    static let doctrines: [Law] = procedure + evidence + defenses + sentencing + ethics

    static let procedure: [Law] = [
        Law(id: "juryWaiver", statute: "N.C. Const. art. I, § 24; G.S. 15A-1201", title: "Bench Trials and Jury Waiver", category: .procedure,
            summary: "Since 2014, a defendant in a non-capital case in superior court may waive a jury, in writing or on the record, with the consent of the trial judge. The judge then decides the facts as well as the law.",
            elements: ["The defendant must give notice of intent to waive at or within 10 working days after arraignment, or within 10 working days after the final administrative setting (G.S. 15A-1201(c)).",
                       "The judge must personally address the defendant to confirm the waiver is knowing and voluntary and that the defendant understands the consequences (G.S. 15A-1201(d)).",
                       "The State may be heard on the waiver, but cannot veto it; the judge decides whether to consent. Capital cases cannot be tried without a jury.",
                       "The judge must disregard evidence that was suppressed or struck.",
                       "The judge weighs witness credibility: bias, interest, opportunity to observe, and consistency.",
                       "Misdemeanors are first tried by a district court judge without a jury. A defendant may appeal for a trial de novo in superior court."],
            related: ["burdenOfProof", "appeals"]),
        Law(id: "burdenOfProof", statute: "N.C. Const. art. I, § 19 (law of the land)", title: "Presumption of Innocence & Reasonable Doubt", category: .procedure,
            summary: "The defendant is presumed innocent. The State must prove every element of every offense beyond a reasonable doubt.",
            elements: ["A reasonable doubt is one based on reason and common sense, arising from the evidence or lack of evidence. It is not a vain, imaginary, or fanciful doubt.",
                       "Proof beyond a reasonable doubt fully satisfies or entirely convinces the fact-finder of the defendant's guilt.",
                       "The defendant's decision not to testify may not be held against them."],
            related: ["juryWaiver", "lesserIncluded"]),
        Law(id: "lesserIncluded", statute: "Case law", title: "Lesser-Included Offenses", category: .procedure,
            summary: "A fact-finder may convict of a lesser offense whose elements are entirely included in the charged offense, when the evidence supports it.",
            elements: ["Example: Robbery with a dangerous weapon → common law robbery, if the weapon is not proven.",
                       "Example: Second-degree murder → voluntary manslaughter, if malice is negated by heat of passion or imperfect self-defense.",
                       "The lesser offense still must be proven beyond a reasonable doubt."],
            related: ["burdenOfProof"]),
        Law(id: "searchSeizure", statute: "U.S. Const. amend. IV; N.C. Const. art. I, § 20", title: "Search and Seizure", category: .procedure,
            summary: "Searches generally require a warrant supported by probable cause. Evidence obtained in substantial violation of constitutional rights or Chapter 15A must be suppressed (G.S. 15A-974).",
            elements: ["A search occurs when officers intrude on a reasonable expectation of privacy.",
                       "Warrants must describe the place to be searched with particularity.",
                       "Searching a cell phone's data requires a warrant, even after arrest (Riley v. California).",
                       "Historical cell-site location records require a warrant (Carpenter v. United States).",
                       "A traffic stop requires reasonable suspicion of a violation or crime."],
            related: ["warrantExceptions", "fruitPoisonousTree", "suppressionProcedure"]),
        Law(id: "eyewitnessID", statute: "G.S. 15A-284.52; Manson v. Brathwaite", title: "Eyewitness Identification", category: .procedure,
            summary: "Lineups must follow the Eyewitness Identification Reform Act: an independent administrator who doesn't know the suspect, at least five fillers who fit the description, instructions that the perpetrator may not be present, and a confidence statement. An identification from an unnecessarily suggestive procedure is excluded if it is unreliable under the totality of the circumstances.",
            elements: ["Failure to follow the Act is evidence the court and jury may consider; it doesn't automatically require suppression.",
                       "Due process excludes an identification only when the procedure was unnecessarily suggestive and created a substantial likelihood of misidentification.",
                       "Reliability factors: the witness's opportunity to view, degree of attention, accuracy of the prior description, certainty, and the time between the crime and the identification.",
                       "A one-person show-up is inherently suggestive but can be justified shortly after the crime, near the scene."],
            related: ["searchSeizure", "suppressionProcedure"]),
        Law(id: "indictment", statute: "G.S. 15A-924; N.C. Const. art. I, § 22", title: "Sufficiency of the Indictment", category: .procedure,
            summary: "A felony may be tried only on a valid indictment that alleges every element of the offense. A facially defective indictment fails to give the court jurisdiction over that count.",
            elements: ["The indictment must allege facts supporting every element of the offense charged.",
                       "In larceny, the indictment must name an owner or possessor of the property who is a person or a legal entity capable of owning property.",
                       "A fatal variance between the indictment and the proof requires dismissal of the count.",
                       "Since State v. Singleton (2023), most defects are reviewed for prejudice; a failure to charge a crime at all remains jurisdictional."],
            related: ["doubleJeopardy"]),
        Law(id: "warrantExceptions", statute: "Case law; G.S. 15A-221 to -223", title: "Exceptions to the Warrant Requirement", category: .procedure,
            summary: "A warrantless search is unreasonable unless an established exception applies.",
            elements: ["Consent: voluntary, by someone with authority (G.S. 15A-222).",
                       "Plain view: officer lawfully present, incriminating nature immediately apparent.",
                       "Exigent circumstances: emergency aid, hot pursuit, imminent destruction of evidence.",
                       "Search incident to arrest: the person and area within immediate control.",
                       "Motor vehicle exception: probable cause the vehicle contains evidence.",
                       "Good faith: G.S. 15A-974(a)(2) does not require suppression when officers objectively relied in good faith on a warrant later found invalid."],
            related: ["searchSeizure", "fruitPoisonousTree"]),
        Law(id: "fruitPoisonousTree", statute: "Case law", title: "Fruit of the Poisonous Tree", category: .procedure,
            summary: "Evidence derived from an unconstitutional search or interrogation is also excluded, unless an exception applies.",
            elements: ["Independent source: also obtained through a separate, lawful route.",
                       "Inevitable discovery: officers would certainly have found it lawfully.",
                       "Attenuation: the connection is too remote."],
            related: ["searchSeizure", "warrantExceptions"]),
        Law(id: "suppressionProcedure", statute: "G.S. 15A-974, -977", title: "Motions to Suppress", category: .procedure,
            summary: "Defendants move to suppress evidence before trial. The judge holds a hearing, makes findings of fact and conclusions of law, and rules.",
            elements: ["The State may appeal an order granting suppression before trial if the prosecutor certifies the evidence is essential (G.S. 15A-979(c)).",
                       "The defendant may raise a denied suppression motion on appeal after conviction."],
            related: ["searchSeizure", "miranda"]),
        Law(id: "miranda", statute: "U.S. Const. amend. V", title: "Miranda Warnings", category: .procedure,
            summary: "Statements from custodial interrogation are inadmissible unless the suspect was warned and validly waived their rights.",
            elements: ["Miranda applies only when there is BOTH custody and interrogation.",
                       "Volunteered statements are admissible.",
                       "When a suspect unambiguously requests counsel, questioning must stop (Edwards v. Arizona).",
                       "In North Carolina, juveniles have additional statutory protections (G.S. 7B-2101)."],
            related: ["voluntariness", "rightToCounsel"]),
        Law(id: "voluntariness", statute: "U.S. Const. amend. XIV", title: "Involuntary Confessions", category: .procedure,
            summary: "A confession obtained by coercion is inadmissible regardless of Miranda warnings. Courts weigh the totality of the circumstances.",
            elements: ["Factors: length of interrogation, deprivation, threats, promises of leniency, the defendant's age and mental condition.",
                       "A promise that a suspect can go home or keep their children if they confess weighs heavily toward involuntariness."],
            related: ["miranda"]),
        Law(id: "rightToCounsel", statute: "U.S. Const. amend. VI; G.S. 7A-450", title: "Right to Counsel", category: .procedure,
            summary: "An indigent defendant facing possible imprisonment is entitled to appointed counsel, through a public defender office or the Office of Indigent Defense Services.",
            elements: ["Applies at every critical stage after formal charges."],
            related: ["miranda"]),
        Law(id: "speedyTrial", statute: "U.S. Const. amend. VI; N.C. Const. art. I, § 18", title: "Right to a Speedy Trial", category: .procedure,
            summary: "Unreasonable delay in bringing a defendant to trial violates the constitution and requires dismissal.",
            elements: ["Barker v. Wingo factors: (1) length of delay, (2) reason for delay, (3) whether the defendant asserted the right, (4) prejudice to the defendant.",
                       "Delay caused by the defense weighs against the defendant.",
                       "Prejudice includes prolonged pretrial incarceration and lost witnesses."],
            related: ["doubleJeopardy"]),
        Law(id: "doubleJeopardy", statute: "U.S. Const. amend. V; N.C. Const. art. I, § 19", title: "Double Jeopardy", category: .procedure,
            summary: "A person may not be tried twice for the same offense. An acquittal is final and cannot be appealed by the State.",
            elements: ["In a bench trial, jeopardy attaches when the first witness is sworn.", "A defendant may appeal a conviction, and a new trial after reversal does not violate double jeopardy."],
            related: ["appeals"]),
        Law(id: "appeals", statute: "G.S. 15A-1442, -1443", title: "Appeals and Prejudicial Error", category: .procedure,
            summary: "A defendant convicted in superior court appeals to the North Carolina Court of Appeals (G.S. 7A-27(b)), including in life-without-parole cases. Only death sentences go directly to the Supreme Court. A new trial is ordered only for prejudicial error.",
            elements: ["Non-constitutional error is prejudicial if there is a reasonable possibility that a different result would have been reached without it (G.S. 15A-1443(a)).",
                       "Constitutional error is prejudicial unless the State shows it was harmless beyond a reasonable doubt (G.S. 15A-1443(b)).",
                       "Insufficient evidence on an element requires the conviction to be vacated."],
            related: ["doubleJeopardy", "juryWaiver"]),
        Law(id: "probationViolation", statute: "G.S. 15A-1344, -1345", title: "Probation Violations", category: .procedure,
            summary: "At a violation hearing, the judge need only be reasonably satisfied, in their discretion, that the probationer willfully violated a condition. This is not proof beyond a reasonable doubt.",
            elements: ["Under the Justice Reinvestment Act, probation may be revoked only for committing a new criminal offense, absconding, or after two prior periods of confinement in response to violation (CRV).",
                       "A probationer may be found in violation for a new offense even without a conviction.",
                       "Options include revoking and activating the suspended sentence, modifying conditions, extending probation, or continuing it unchanged."],
            related: ["dispositions"])
    ]

    static let evidence: [Law] = [
        Law(id: "hearsay", statute: "N.C. R. Evid. 801, 802", title: "Hearsay", category: .evidence,
            summary: "An out-of-court statement offered to prove the truth of the matter asserted is inadmissible unless an exception applies.",
            elements: ["\"My neighbor told me the defendant did it\" is hearsay.",
                       "Statements offered for another purpose (e.g. to explain why someone acted) are not hearsay.",
                       "A party's own statement offered against them is not hearsay (Rule 801(d))."],
            related: ["hearsayExceptions", "partyAdmission"]),
        Law(id: "hearsayExceptions", statute: "N.C. R. Evid. 803, 804", title: "Hearsay Exceptions", category: .evidence,
            summary: "Some out-of-court statements are admissible because the circumstances make them reliable.",
            elements: ["Excited utterance (803(2)): made under the stress of a startling event.",
                       "Present sense impression (803(1)): describing an event as it happens.",
                       "Business records (803(6)).",
                       "Statement against interest (804(b)(3)): by an unavailable declarant, exposing them to criminal liability; corroboration required when offered to exculpate the accused.",
                       "Dying declaration (804(b)(2))."],
            related: ["hearsay"]),
        Law(id: "partyAdmission", statute: "N.C. R. Evid. 801(d)", title: "Admission by a Party-Opponent", category: .evidence,
            summary: "A defendant's own statements, offered by the State, are admissible as admissions.",
            elements: ["Only when offered against the party who made them.", "A defendant cannot introduce their own self-serving out-of-court statements this way."],
            related: ["hearsay", "miranda"]),
        Law(id: "leading", statute: "N.C. R. Evid. 611(c)", title: "Leading Questions", category: .evidence,
            summary: "Leading questions, which suggest the answer, are generally improper on direct examination but permitted on cross-examination.",
            elements: ["Direct: \"You saw the defendant holding the gun, didn't you?\" is improper.", "Cross: \"You had been drinking that night, hadn't you?\" is proper."],
            related: ["speculation"]),
        Law(id: "speculation", statute: "N.C. R. Evid. 602, 701", title: "Personal Knowledge & Lay Opinion", category: .evidence,
            summary: "A witness may testify only to matters within personal knowledge. Lay opinions must be rationally based on perception and helpful.",
            elements: ["\"I bet the police framed him\" is speculation.", "A non-expert's opinion that injuries were intentional requires expertise."],
            related: ["expertTestimony"]),
        Law(id: "characterEvidence", statute: "N.C. R. Evid. 404(a)", title: "Character Evidence", category: .evidence,
            summary: "Evidence of character is not admissible to prove that a person acted in conformity with it, with limited exceptions.",
            elements: ["The State may not argue \"they're a bad person, so they did it.\"",
                       "An accused may offer evidence of a pertinent character trait (e.g. peacefulness or honesty), which opens the door to rebuttal."],
            related: ["priorActs"]),
        Law(id: "priorActs", statute: "N.C. R. Evid. 404(b)", title: "Other Crimes, Wrongs, or Acts", category: .evidence,
            summary: "Other acts are inadmissible to show propensity, but may be admitted for motive, opportunity, intent, plan, knowledge, identity, or absence of mistake.",
            elements: ["North Carolina treats 404(b) as a rule of inclusion, subject to the requirements of similarity and temporal proximity.",
                       "A threat against the same victim days before is admissible to show motive and intent."],
            related: ["characterEvidence", "relevance"]),
        Law(id: "relevance", statute: "N.C. R. Evid. 401–403", title: "Relevance & Unfair Prejudice", category: .evidence,
            summary: "Evidence must have a tendency to make a fact of consequence more or less probable. Relevant evidence may be excluded if its probative value is substantially outweighed by unfair prejudice.",
            elements: ["A victim's unrelated past is usually irrelevant."],
            related: ["characterEvidence"]),
        Law(id: "chainOfCustody", statute: "N.C. R. Evid. 901", title: "Authentication & Chain of Custody", category: .evidence,
            summary: "Physical evidence must be shown to be what it purports to be. Weak links in the chain of custody generally go to weight, not admissibility.",
            elements: ["Fungible items such as drugs require a more detailed chain."],
            related: ["expertTestimony"]),
        Law(id: "expertTestimony", statute: "N.C. R. Evid. 702", title: "Expert Testimony", category: .evidence,
            summary: "Since 2011, North Carolina follows the Daubert standard: expert testimony must be based on sufficient facts, reliable principles and methods, and reliable application.",
            elements: ["Consider testability, peer review, error rate, and general acceptance.",
                       "Traditional arson indicators such as \"pour patterns\" and \"crazed glass\" have been discredited by modern fire science (NFPA 921)."],
            related: ["chainOfCustody"])
    ]

    static let defenses: [Law] = [
        Law(id: "selfDefense", statute: "G.S. 14-51.2, 14-51.3", title: "Self-Defense", category: .defenses,
            summary: "A person is justified in using deadly force, with no duty to retreat from any place they have a lawful right to be, if they reasonably believe it is necessary to prevent imminent death or great bodily harm.",
            elements: ["The belief must be both actual and reasonable.",
                       "Non-deadly force is justified against imminent unlawful force.",
                       "The initial aggressor generally loses the right, unless they withdraw (G.S. 14-51.4).",
                       "Castle doctrine: an occupant is presumed to fear death when using force against an unlawful, forcible entry into a home, vehicle, or workplace.",
                       "Once evidence of self-defense is presented, the State must prove beyond a reasonable doubt that the defendant did not act in self-defense."],
            related: ["imperfectSelfDefense", "defenseOfOthers"]),
        Law(id: "imperfectSelfDefense", statute: "Case law", title: "Imperfect Self-Defense", category: .defenses,
            summary: "If the defendant actually believed deadly force was necessary, but the belief was unreasonable, or the defendant was the aggressor without murderous intent, or used excessive force, murder is reduced to voluntary manslaughter.",
            elements: ["It lowers the degree of the crime; it is not a complete defense."],
            related: ["selfDefense", "volManslaughter"]),
        Law(id: "batteredSpouse", statute: "State v. Norman, 324 N.C. 253 (1989)", title: "Battered Spouse Syndrome & Imminence", category: .defenses,
            summary: "Evidence of long-term abuse and expert testimony on battered spouse syndrome may help explain the defendant's state of mind. But in North Carolina, self-defense still requires a belief in imminent death or great bodily harm.",
            elements: ["In State v. Norman, a wife killed her severely abusive husband while he slept. The Supreme Court of North Carolina held she was not entitled to a self-defense instruction, because no threat was imminent at that moment.",
                       "Evidence of abuse remains relevant to imperfect self-defense, provocation, and sentencing (as a mitigating factor).",
                       "Many commentators criticize Norman. It remains the law."],
            related: ["selfDefense", "imperfectSelfDefense", "volManslaughter"]),
        Law(id: "defenseOfOthers", statute: "G.S. 14-51.3", title: "Defense of Others", category: .defenses,
            summary: "Force may be used to defend another person under the same conditions as self-defense.",
            elements: ["The defender must reasonably believe the other person faces imminent unlawful force."],
            related: ["selfDefense"]),
        Law(id: "insanity", statute: "Case law (M'Naghten)", title: "Insanity", category: .defenses,
            summary: "Not guilty by reason of insanity if, due to a disease or defect of the mind, the defendant did not know the nature and quality of the act, or did not know it was wrong.",
            elements: ["The defendant bears the burden of proving insanity to the satisfaction of the fact-finder.", "An acquittal leads to civil commitment proceedings."],
            related: ["expertTestimony"]),
        Law(id: "duress", statute: "Case law", title: "Duress", category: .defenses,
            summary: "A defense when the defendant acted under a reasonable fear of imminent death or serious bodily harm, with no reasonable opportunity to escape.",
            elements: ["Not a defense to murder.", "Unavailable if the defendant recklessly placed themselves in the situation."],
            related: ["necessity"]),
        Law(id: "necessity", statute: "Case law", title: "Necessity", category: .defenses,
            summary: "Conduct is excused when done to avoid a greater, imminent harm, with no reasonable legal alternative.",
            elements: ["The harm avoided must be greater than the harm caused.", "The danger must be imminent.", "Economic necessity almost never qualifies."],
            related: ["justification", "duress"]),
        Law(id: "justification", statute: "State v. Mercer, 373 N.C. 459 (2020)", title: "Justification for Firearm Possession", category: .defenses,
            summary: "A felon may possess a firearm when justified by an emergency, but only within narrow limits.",
            elements: ["The defendant was under unlawful and present, imminent, and impending threat of death or serious bodily injury.",
                       "The defendant did not negligently or recklessly place themselves in the situation.",
                       "There was no reasonable legal alternative.",
                       "There was a direct causal relationship between the criminal action and avoiding the threatened harm.",
                       "Carrying a gun for general protection against future threats does not qualify."],
            related: ["felonFirearm", "necessity"]),
        Law(id: "entrapment", statute: "Case law", title: "Entrapment", category: .defenses,
            summary: "A defense when law enforcement induced the crime through trickery, persuasion, or fraud, and the criminal design originated with officers rather than with a predisposed defendant.",
            elements: ["Merely providing an opportunity is not entrapment.", "The defendant bears the burden of proving entrapment."],
            related: ["bribery"]),
        Law(id: "intoxication", statute: "Case law", title: "Voluntary Intoxication", category: .defenses,
            summary: "Voluntary intoxication is not a defense to general-intent crimes, but may negate the specific intent required for first-degree murder.",
            elements: ["The intoxication must be so great that the defendant was utterly incapable of forming the required intent."],
            related: ["murder1"]),
        Law(id: "alibi", statute: "G.S. 15A-905(c)", title: "Alibi", category: .defenses,
            summary: "Evidence that the defendant was elsewhere when the crime occurred. The defense must give notice of an alibi if ordered in discovery.",
            elements: ["Alibi witnesses close to the defendant may be biased, but are not automatically disbelieved."],
            related: ["burdenOfProof"]),
        Law(id: "mistakeOfFact", statute: "Case law", title: "Mistake of Fact", category: .defenses,
            summary: "An honest and reasonable mistake that negates a required mental state is a defense.",
            elements: ["Believing the property was one's own negates intent to steal."],
            related: ["felonyLarceny"])
    ]

    static let sentencing: [Law] = [
        Law(id: "punishmentChart", statute: "G.S. 15A-1340.17", title: "Felony Punishment Chart", category: .sentencing,
            summary: "Felony sentences are set by the offense class and the defendant's prior record level. Each cell lists the permitted dispositions and mitigated, presumptive, and aggravated ranges for the minimum sentence.",
            elements: ["Choose the range: presumptive by default; aggravated or mitigated only after finding factors.",
                       "Choose a minimum term within that range. The maximum is set by statute.",
                       "Choose a disposition allowed in the cell: Active, Intermediate, or Community.",
                       "Class A felonies are punished by life without parole (or death). Class B1 at level V or VI may receive life without parole in the aggravated range."],
            related: ["priorRecord", "aggravatingFactors", "dispositions"]),
        Law(id: "priorRecord", statute: "G.S. 15A-1340.14", title: "Prior Record Level", category: .sentencing,
            summary: "Prior convictions are assigned points by class. The total sets the prior record level.",
            elements: ["Class A prior: 10 points. B1: 9. B2, C, or D: 6. E, F, or G: 4. H or I: 2. Class A1 or 1 non-traffic misdemeanor (or impaired driving): 1.",
                       "+1 if the offense was committed while on probation, parole, or post-release supervision, or while serving a sentence or on escape.",
                       "+1 if all elements of the present offense are included in a prior offense.",
                       "Level I: 0–1 points. II: 2–5. III: 6–9. IV: 10–13. V: 14–17. VI: 18+."],
            related: ["punishmentChart", "habitualFelon"]),
        Law(id: "misdemeanorSentencing", statute: "G.S. 15A-1340.20–.23", title: "Misdemeanor Sentencing", category: .sentencing,
            summary: "Misdemeanor sentences depend on the class and the number of prior convictions: Level I (none), II (1–4), III (5+).",
            elements: ["Class A1: up to 60 / 75 / 150 days; any disposition.",
                       "Class 1: up to 45 days (community only at Level I) / 45 / 120 days.",
                       "Class 2: up to 30 / 45 / 60 days; fine up to $1,000.",
                       "Class 3: up to 10 / 15 / 20 days; fine up to $200.",
                       "Active misdemeanor sentences are served in local jail or through the Statewide Misdemeanant Confinement Program."],
            related: ["dispositions"]),
        Law(id: "aggravatingFactors", statute: "G.S. 15A-1340.16", title: "Aggravating & Mitigating Factors", category: .sentencing,
            summary: "The judge may depart from the presumptive range into the aggravated or mitigated range after finding factors and determining which outweigh the others.",
            elements: ["Aggravating factors include: especially heinous, atrocious, or cruel; victim very young, very old, or infirm; taking advantage of a position of trust; use of a deadly weapon; great monetary loss; committed while on pretrial release.",
                       "Aggravating factors must be proven beyond a reasonable doubt (or admitted), and the State must give notice.",
                       "Mitigating factors include: duress or strong provocation; passive participant; reduced capacity due to a mental or physical condition; acceptance of responsibility; support system in the community; positive employment history; good character; treatment participation.",
                       "Mitigating factors are proven by a preponderance of the evidence.",
                       "Whether to depart is within the judge's discretion, even when factors are found."],
            related: ["punishmentChart"]),
        Law(id: "dispositions", statute: "G.S. 15A-1340.11, -1343.2", title: "Active, Intermediate & Community Punishment", category: .sentencing,
            summary: "Each chart cell lists which dispositions are allowed.",
            elements: ["Active: the defendant goes to prison (felonies) or jail (misdemeanors).",
                       "Intermediate: suspended sentence with supervised probation. Since the Justice Reinvestment Act of 2011, it may include special probation or Drug Treatment Court, plus any community condition.",
                       "Community: suspended sentence with supervised or unsupervised probation, a fine, or both. It may include house arrest with electronic monitoring, community service, short \"quick dip\" jail stays, and TASC or other treatment, but not special probation or Drug Treatment Court.",
                       "Felony probation is generally 12–30 months (community) or 18–36 months (intermediate).",
                       "Misdemeanor probation is generally 6–18 months (community) or 12–24 months (intermediate)."],
            related: ["punishmentChart", "probationViolation"]),
        Law(id: "postRelease", statute: "G.S. 15A-1368 to -1368.6", title: "Post-Release Supervision", category: .sentencing,
            summary: "North Carolina abolished parole for offenses after 1994. Felons serve at least the minimum term, then are released onto post-release supervision for the remainder.",
            elements: ["Class F–I felons: 9 months of post-release supervision, built into the maximum (G.S. 15A-1368.2).",
                       "Class B1–E felons: 12 months, built into the maximum.",
                       "Offenses requiring sex offender registration: 5 years.",
                       "Earned time may reduce the sentence toward, but never below, the minimum."],
            related: ["punishmentChart"]),
        Law(id: "consolidation", statute: "G.S. 15A-1340.15", title: "Multiple Convictions", category: .sentencing,
            summary: "When a defendant is convicted of more than one offense, the judge may consolidate them into a single judgment, or enter separate judgments to run concurrently or consecutively.",
            elements: ["A consolidated judgment is sentenced at the class of the most serious offense.",
                       "Sentences run concurrently unless the judge specifies consecutive."],
            related: ["punishmentChart"]),
        Law(id: "habitualFelon", statute: "G.S. 14-7.1 to -7.6", title: "Habitual Felon Status", category: .sentencing,
            summary: "A person with three prior felony convictions (each committed after the previous conviction) may be indicted as a habitual felon. If the status is found, the person is sentenced four classes higher than the principal felony, but no higher than Class C.",
            elements: ["Habitual felon is a status, not a crime. It is tried after a conviction on the principal felony.",
                       "Convictions used to establish the status may not also be counted for prior record points.",
                       "Example: a Class H felony becomes Class D for sentencing."],
            related: ["priorRecord", "punishmentChart"]),
        Law(id: "pjc", statute: "Case law; G.S. 15A-1331, -1331.2", title: "Prayer for Judgment Continued (PJC)", category: .sentencing,
            summary: "After a finding of guilt, the court may continue prayer for judgment: no sentence is imposed and no final judgment is entered. Common for minor misdemeanors.",
            elements: ["If the court attaches conditions amounting to punishment (beyond costs or obeying the law), the PJC becomes a final judgment.",
                       "A PJC still counts as a prior conviction for prior record purposes.",
                       "A PJC is not allowed for Class A through E felonies (G.S. 15A-1331.2), or for impaired driving.",
                       "The State may later pray for judgment within a reasonable time."],
            related: ["misdemeanorSentencing"]),
        Law(id: "probationConditions", statute: "G.S. 15A-1343", title: "Conditions of Probation", category: .sentencing,
            summary: "Every probationary sentence carries regular conditions. The court may add special conditions reasonably related to rehabilitation.",
            elements: ["Regular conditions include: commit no criminal offense, remain within the jurisdiction, report as directed, possess no firearm, pay money owed, and submit to warrantless searches (if supervised).",
                       "Special conditions include: substance abuse or mental health treatment, community service, curfew, no-contact orders, abstaining from alcohol, maintaining employment or education, and surrendering firearms.",
                       "Intermediate conditions include special probation, house arrest with electronic monitoring, and Drug Treatment Court.",
                       "Supervision carries a $40 monthly fee; community service carries a $250 fee. The court may waive fees for good cause."],
            related: ["specialProbation", "dispositions", "probationViolation", "monetaryObligations"]),
        Law(id: "specialProbation", statute: "G.S. 15A-1351", title: "Special Probation (Split Sentence)", category: .sentencing,
            summary: "As a condition of probation, the court may require the defendant to serve a period of time in jail or prison, then be released on probation.",
            elements: ["The total period of special probation may not exceed one-fourth of the maximum sentence imposed.",
                       "It may be served in continuous or noncontinuous periods, such as weekends.",
                       "Special probation is an intermediate condition."],
            related: ["probationConditions", "dispositions"]),
        Law(id: "asr", statute: "G.S. 15A-1340.18", title: "Advanced Supervised Release (ASR)", category: .sentencing,
            summary: "For eligible active sentences, the court may order ASR. A prisoner who completes risk-reduction incentives is released at the lowest minimum of the mitigated range for that class and level.",
            elements: ["Available only if the prosecutor does not object.",
                       "Only for sentences in the presumptive or mitigated range.",
                       "Release is onto post-release supervision; failure there returns the person to prison."],
            related: ["punishmentChart", "postRelease"],
            notes: "Eligible: Class D at prior record levels I–III, Class E at I–IV, Class F at I–V, and Class G or H at any level. A presumptive-range sentence releases at the bottom of the mitigated range; a mitigated-range sentence releases at 80 percent of the minimum."),
        Law(id: "monetaryObligations", statute: "G.S. 7A-304, 7A-455, 15A-1340.36, 15A-1343(c1)", title: "Fines, Costs, Fees & Restitution", category: .sentencing,
            summary: "A judgment may include a fine, court costs, restitution, attorney fees for appointed counsel, and supervision and program fees.",
            elements: ["Court costs are taxed by statute unless the court finds just cause to waive them.",
                       "Restitution compensates the victim for losses; the court must consider the defendant's ability to pay in setting the amount and schedule.",
                       "Appointed counsel fees are entered as a civil judgment against the defendant, after notice and an opportunity to be heard. A $60 appointment fee also applies (G.S. 7A-455.1).",
                       "A $600 fee applies when the State Crime Laboratory analyzed evidence in the case (G.S. 7A-304(a)(7)).",
                       "Unpaid money is a common basis for probation violation reports. Non-willful failure to pay cannot support revocation."],
            related: ["probationConditions", "victimRights"]),
        Law(id: "crv", statute: "G.S. 15A-1344(d2)", title: "Confinement in Response to Violation (CRV)", category: .sentencing,
            summary: "For violations that don't allow revocation, the court may order a 90-day period of confinement (felony) or up to 90 days (misdemeanor), after which probation resumes.",
            elements: ["Revocation is permitted only for a new criminal offense, absconding, or after two prior CRVs.",
                       "Short \"quick dip\" jail stays of 2–3 days may also be imposed as a sanction.",
                       "Time served on a CRV is credited against the suspended sentence."],
            related: ["probationViolation", "probationConditions"]),
        Law(id: "conditionalDischarge", statute: "G.S. 90-96; 15A-1341(a4)", title: "Conditional Discharge", category: .sentencing,
            summary: "The court defers judgment and places the defendant on probation; on successful completion the charge is dismissed and no conviction is entered.",
            elements: ["G.S. 90-96(a): for eligible first-time drug possession, with no prior felony or drug conviction, the court must order a conditional discharge with the defendant's consent unless it finds the defendant inappropriate.",
                       "G.S. 15A-1341(a4): for a Class H or I felony or any misdemeanor, the court may order a conditional discharge on joint motion of the defendant and the State, if the defendant has no prior felony and no prior discharge.",
                       "A person may receive only one conditional discharge."],
            related: ["possSchedII"]),
        Law(id: "victimRights", statute: "N.C. Const. art. I, § 37 (Marsy's Law)", title: "Victims' Rights", category: .sentencing,
            summary: "Victims have the right to be present and reasonably heard at sentencing, and to receive restitution.",
            elements: ["Victim impact statements inform, but do not dictate, the sentence."],
            related: ["aggravatingFactors"])
    ]

    static let ethics: [Law] = [
        Law(id: "exParte", statute: "N.C. Code of Judicial Conduct, Canon 3A(4)", title: "Ex Parte Communications", category: .ethics,
            summary: "A judge should not initiate or consider ex parte or other communications concerning a pending proceeding, outside the presence of the parties.",
            elements: ["If one is received, the usual practice is to disclose it to all parties and allow them to respond."],
            related: ["disqualification", "judicialStandards"]),
        Law(id: "disqualification", statute: "N.C. Code of Judicial Conduct, Canon 3C", title: "Disqualification", category: .ethics,
            summary: "A judge should disqualify themselves in proceedings where their impartiality may reasonably be questioned.",
            elements: ["Personal bias, family relationships, and financial interests require disqualification.", "Parties may agree to waive some grounds after disclosure on the record (Canon 3D)."],
            related: ["exParte"]),
        Law(id: "publicComment", statute: "N.C. Code of Judicial Conduct, Canon 3A(6)", title: "Public Comment on Pending Cases", category: .ethics,
            summary: "A judge should abstain from public comment about the merits of a pending proceeding.",
            elements: ["Explaining court procedures to the public is permitted."],
            related: ["exParte"]),
        Law(id: "gifts", statute: "N.C. Code of Judicial Conduct, Canon 5C(4)", title: "Gifts", category: .ethics,
            summary: "A judge should not accept gifts from anyone whose interests have come or are likely to come before the judge.",
            elements: ["Ordinary social hospitality from people without matters before the court is permitted."],
            related: ["disqualification"]),
        Law(id: "judicialStandards", statute: "G.S. 7A-374.1 et seq.", title: "Judicial Standards Commission", category: .ethics,
            summary: "The Judicial Standards Commission investigates complaints against North Carolina judges. Its proceedings are confidential until it issues a public reprimand or recommends discipline to the Supreme Court.",
            elements: ["The Commission itself may issue a private letter of caution or a public reprimand.",
                       "For more serious misconduct it recommends that the Supreme Court censure, suspend, or remove the judge."],
            related: ["exParte"])
    ]
}
